Author: jlaznarte<br>Date: Tue Dec 18 02:36:08 2007<br>New Revision: 98<p>Added:<br>   trunk/tsDyn/R/ncstar.R<p>Log:<br>First quasi-working version of the NCSTAR model.<p>Still with trouble in startingValues.<p><p>Added: trunk/tsDyn/R/ncstar.R<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/ncstar.R	Tue Dec 18 02:36:08 2007<br>@@ -0,0 +1,1222 @@<br>+## Copyright (C) 2005, 2006, 2007  Antonio, Fabio Di Narzo;<br>+##                                                           Jos� Luis <br>Aznarte M.<br>+##<br>+## This program is free software; you can redistribute it and/or modify<br>+## it under the terms of the GNU General Public License as published by<br>+## the Free Software Foundation; either version 2, or (at your option)<br>+## any later version.<br>+##<br>+## This program is distributed in the hope that it will be useful, but<br>+## WITHOUT ANY WARRANTY; without even the implied warranty of<br>+## MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU<br>+## General Public License for more details.<br>+##<br>+## A copy of the GNU General Public License is available via WWW at<br>+## <a href="http://www.gnu.org/copyleft/gpl.html" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://www.gnu.org/copyleft/gpl.html&amp;source=gmail&amp;ust=1792465631321000&amp;usg=AOvVaw2e-XU6zIH4MEx0yFoYzo5S">http://www.gnu.org/copyleft/gpl.html</a>.  You can also obtain it by<br>+## writing to the Free Software Foundation, Inc., 59 Temple Place,<br>+## Suite 330, Boston, MA  02111-1307  USA.<br>+<br>+#Logistic transition function<br>+# z: transition variables<br>+# gamma: smoothing parameters<br>+# th: threshold values<br>+G &lt;- function(z, gamma, th) {<br>+  if((length(th) &gt; 1) &amp;&amp; (length(gamma) &gt; 1))<br>+    t( apply( as.matrix(z) , 1, plogis, th, 1/gamma) )<br>+  else<br>+    plogis(z, th, 1/gamma)<br>+}<br>+<br>+# Computes the gradient<br>+#<br>+# object: a valid STAR model.<br>+#<br>+# Returns a list of the gradients with respect to  the linear and<br>+#     nonlinear parameters<br>+computeGradient.ncstar &lt;- function(object, ...)<br>+{<br>+<br>+  noRegimes &lt;- object$model.specific$noRegimes;<br>+  n.used &lt;- NROW(object$str$xx);<br>+  x_t &lt;- cbind(1, object$str$xx);<br>+  xx &lt;- object$str$xx;<br>+<br>+  phi2omega &lt;- object$model.specific$phi2omega<br>+<br>+  # phi2 contains parameters gamma and th for each regime<br>+  phi2 &lt;- phi2omega[1:((noRegimes-1) * 2)];<br>+  dim(phi2) &lt;- c(noRegimes - 1, 2)<br>+<br>+  gamma &lt;- phi2[,1]<br>+  th &lt;- phi2[,2]<br>+<br>+  # omega (one vector for each regime)<br>+  omega &lt;- phi2omega[(((noRegimes - 1) * 2) + 1):length(phi2omega)]<br>+  dim(omega) &lt;- c(NCOL(xx), noRegimes - 1)<br>+<br>+  # linear parameters<br>+  phi1 &lt;- object$model.specific$phi1;<br>+<br>+  fX &lt;- array(0, c(noRegimes - 1, n.used));<br>+  dfX &lt;- array(0, c(noRegimes - 1, n.used));<br>+  gPhi1 &lt;- x_t;<br>+  for (i in 1:(noRegimes - 1)) {<br>+    fX[i,] &lt;- sigmoid(gamma[i] * (xx %*% omega[,i] - th[i]));<br>+    dfX[i,] &lt;- sigmoid(gamma[i] * (xx %*% omega[,i] - th[i])) *<br>+                                        (1 - sigmoid(gamma[i] * <br>(xx %*% omega[,i] - th[i])));<br>+    gPhi1 &lt;- cbind(gPhi1, kronecker(matrix(1, 1, NCOL(x_t)), fX[i,]) * x_t)<br>+  }<br>+<br>+  gTh &lt;- array(0, c(n.used, noRegimes-1))<br>+  gGamma &lt;- array(0, c(n.used, noRegimes-1));<br>+  gOmega &lt;- array(0, c(n.used, (noRegimes - 1), NCOL(xx)))<br>+  for (i in 1:(noRegimes - 1)) {<br>+    gTh[,i] &lt;-         - (x_t %*% phi1[i + 1,]) * (gamma[i] * dfX[i,]);<br>+    gGamma[, i] &lt;- (x_t %*% phi1[i + 1,]) * (dfX[i,] * (xx %*% <br>omega[,i] - th[i]));<br>+    for (j in 1:NCOL(xx))<br>+      gOmega[, i, j] &lt;-  (x_t %*% phi1[i + 1,]) * (dfX[i,] * gamma[i] <br>* xx[i,j])<br>+  }<br>+  dim(gOmega) &lt;- c(n.used, (noRegimes - 1) * NCOL(xx))<br>+<br>+  return(cbind(gPhi1, gGamma, gTh, gOmega))<br>+<br>+}<br>+<br>+# Tests (within the LM framework), being the null hypothesis H_0 that the<br>+#    model &#39;object&#39; is complex enough and the alternative H_1 that an extra<br>+#    regime should be considered.<br>+#<br>+# object: a STAR model already built with at least 2 regimes.<br>+# G: the gradient matrix obtained by using computeGradient()<br>+# rob: boolean indicating if robust tests should be used or not.<br>+# sig: significance level of the tests<br>+#<br>+# returns a list containing the p-value of the F statistic and a boolean,<br>+#      true if there is some remaining nonlinearity and false otherwise.<br>+testRegime.ncstar &lt;- function(object, G, rob=FALSE, sig=0.05, trace = TRUE, ...)<br>+{<br>+<br>+  e &lt;-  object$residuals;<br>+ # x_t &lt;- object$model.specific$thVar;<br>+  nG &lt;- NCOL(G);<br>+  T &lt;- length(e);<br>+  xx &lt;- object$str$xx<br>+<br>+  normG &lt;- norm(Matrix(t(G)) %*% e)<br>+  norm2G &lt;-  sum(abs(t(G) %*% e)^2)^(1/2)<br>+#  cat(&quot;norm2G = &quot;, norm2G, &quot;normG = &quot;, normG, &quot;
&quot;);<br>+<br>+  # Compute the rank of G&#39; * G<br>+  G2 &lt;- t(G) %*% G;<br>+  s &lt;- svd(G2);<br>+  tol &lt;- max(dim(G2)) * s[1]$d * 2.2204e-16<br>+  rG &lt;- qr(G2, tol)$rank<br>+#  cat(&quot;rango G = &quot;, rG, &quot;
&quot;);<br>+<br>+#  rG &lt;- sum(svd(G2)$d &gt; tol);<br>+<br>+  if (normG &gt; 1e-6) {<br>+    if(rG &lt; nG) {<br>+#      cat(&quot;A1
&quot;)<br>+      PCtmp &lt;- princomp(G);<br>+      PC &lt;- PCtmp$loadings;<br>+#      GPCA &lt;- PCtmp$scores;<br>+      lambda &lt;- cumsum(PCtmp$sdev^2 / sum(PCtmp$sdev^2));<br>+      indmin &lt;- min(which(lambda &gt; 0.99999));<br>+      GPCA &lt;- t(PC%*%t(G));<br>+      GPCA &lt;- GPCA[, 1:indmin];<br>+#      b &lt;- solve(t(GPCA) %*% GPCA) %*% t(GPCA) %*% e;<br>+      b &lt;- lm(e ~ . -1, data = data.frame(GPCA))$coefficients<br>+      dim(b) &lt;- c(NCOL(GPCA), 1);<br>+      u &lt;-  e - GPCA %*% b;<br>+      xH0 &lt;- GPCA;<br>+    } else {<br>+#      cat(&quot;A2
&quot;)<br>+#      b &lt;- solve(t(G) %*% G) %*% t(G) %*% e;<br>+      b &lt;- lm(e ~ . -1, data=data.frame(G))$coefficients;<br>+      u &lt;- e - G %*% b;<br>+      xH0 &lt;- G;<br>+    }<br>+  } else {<br>+    u &lt;- e;<br>+    if(rG &lt; nG) {<br>+#     cat(&quot;B1
&quot;)<br>+      PCtmp &lt;- princomp(G);<br>+      PC &lt;- PCtmp$loadings;<br>+#      GPCA &lt;- PCtmp$scores;<br>+      lambda &lt;- cumsum(PCtmp$sdev^2 / sum(PCtmp$sdev^2));<br>+      indmin &lt;- min(which(lambda&gt; 0.99999));<br>+      GPCA &lt;- t(PC%*%t(G));<br>+      GPCA &lt;- GPCA[, 1:indmin];<br>+      xH0 &lt;- GPCA;<br>+    } else {<br>+#      cat(&quot;B2
&quot;)<br>+      xH0 = G;<br>+    }<br>+  }<br>+<br>+  SSE0 &lt;- sum(u^2);<br>+<br>+  # Regressors under the alternative:<br>+  xH1 &lt;- cbind(xx^2, xx^3, xx^4)<br>+<br>+  Z &lt;- cbind(xH0, xH1)<br>+<br>+  # Standarize the regressors<br>+  nZ &lt;- NCOL(Z);<br>+  sdZ &lt;- sd(Z)<br>+  dim(sdZ) &lt;- c(1, nZ)<br>+  sdZ &lt;- kronecker(matrix(1, T, 1), sdZ) # repeat sdZ T rows<br>+  Z[,2:nZ] &lt;- Z[,2:nZ] / sdZ[,2:nZ]<br>+<br>+   # Compute the rank of Z<br>+  s &lt;- svd(Z);<br>+  tol &lt;- max(dim(Z)) * s[1]$d * 2.2204e-16<br>+  rZ &lt;- qr(Z, tol)$rank<br>+  if(rZ &lt; NCOL(Z)) stop(&quot;Multicollinearity problem.
&quot;)<br>+<br>+ # Nonlinear model (Alternative hypothesis)<br>+#  c &lt;- solve(t(Z) %*% Z) %*% t(Z) %*% u;<br>+  c &lt;- lm(u ~ . - 1, data=data.frame(Z))$coefficients<br>+  dim(c) &lt;- c(NCOL(Z), 1);<br>+  v &lt;- u - Z %*% c;<br>+  SSE &lt;- sum(v^2);<br>+<br>+  # Compute the third order statistic<br>+  nxH0 &lt;- NCOL(xH0);<br>+  nxH1 &lt;- NCOL(xH1);<br>+<br>+  F = ((SSE0 - SSE) / nxH1) / (SSE / (T - nxH0 - nxH1));<br>+<br>+  pValue &lt;- pf(F, nxH1, T - nxH0 - nxH1, lower.tail = FALSE);<br>+<br>+  if (pValue &gt;= sig) {<br>+    return(list(remainingNonLinearity = FALSE, pValue = pValue));<br>+  }<br>+  else {<br>+    return(list(remainingNonLinearity = TRUE, pValue = pValue));<br>+  }<br>+}<br>+<br>+addRegime &lt;- function(object, ...)<br>+  UseMethod(&quot;addRegime.ncstar&quot;)<br>+<br>+addRegime.ncstar &lt;- function(object)<br>+{<br>+<br>+  noRegimes &lt;- object$model.specific$noRegimes<br>+  xx &lt;- object$str$xx<br>+  phi2omega &lt;- object$model.specific$phi2omega<br>+<br>+  if(noRegimes == 1) {<br>+<br>+    # omega is random but has norm equal to 1<br>+    omega &lt;- c(runif(1, 0.000000001, 1), runif(NCOL(xx) - 1, -1,1))<br>+    omega &lt;- omega * (1/norm(Matrix(omega)))<br>+    dim(omega) &lt;- c(NCOL(xx), 1)<br>+<br>+    gamma &lt;- 0<br>+    th &lt;- median(xx %*% omega)<br>+<br>+    phi2 &lt;- cbind(gamma, th);<br>+<br>+    phi1 &lt;-   object$model.specific$phi1<br>+    phi1 &lt;-   rbind(object$model.specific$phi1, rnorm(NCOL(xx) + 1));<br>+<br>+  }<br>+  else {<br>+    # phi2 contains parameters gamma and th for each regime<br>+    phi2 &lt;- phi2omega[1:((noRegimes-1) * 2)];<br>+    dim(phi2) &lt;- c(noRegimes - 1, 2)<br>+<br>+    gamma &lt;- phi2[,1];<br>+    th &lt;- phi2[,2];<br>+<br>+    gamma[noRegimes] &lt;- 0.0; # Add one gamma<br>+    th[noRegimes] &lt;- 0.0;        # Add one th<br>+<br>+    phi2 &lt;- cbind(gamma, th);<br>+<br>+    # omega (one column vector for each regime)<br>+    omega &lt;- phi2omega[(((noRegimes - 1) * 2) + 1):length(phi2omega)]<br>+    dim(omega) &lt;- c(NCOL(xx), noRegimes - 1)<br>+<br>+    newOmega &lt;- c(runif(1, 0.000000001, 1), runif(NCOL(xx) - 1, -1,1))<br>+    newOmega &lt;- newOmega * (1 / norm(Matrix(omega)))<br>+    dim(newOmega) &lt;- c(NCOL(xx), 1)<br>+<br>+    omega &lt;- cbind(omega, newOmega); # Add one (random) vector<br>+<br>+    # phi1 (one vector for each regime)<br>+    phi1 &lt;-   object$model.specific$phi1<br>+    phi1 &lt;-   rbind(object$model.specific$phi1, rnorm(NCOL(xx) + 1));<br>+  }<br>+<br>+  # Update the object<br>+  object$model.specific$noRegimes &lt;- object$model.specific$noRegimes + 1;<br>+  object$noRegimes &lt;- object$noRegimes + 1;<br>+<br>+  object$model.specific$phi1 &lt;- phi1<br>+  object$model.specific$phi2omega &lt;- c(phi2, omega)<br>+<br>+  object$model.specific$coefficients &lt;- c(phi1, c(phi2, omega));<br>+  object$coefficients &lt;- c(phi1, c(phi2, omega));<br>+  object$model.specific$k &lt;- length(object$coefficients)<br>+  object$k &lt;- length(object$coefficients);<br>+<br>+  return(object);<br>+<br>+}<br>+<br>+startingValues &lt;- function(object, ...)<br>+  UseMethod(&quot;startingValues.ncstar&quot;)<br>+<br>+# Find promising initial values for next regime<br>+#<br>+# object: a valid (estimated) STAR model with m regimes<br>+#<br>+# returns a modified copy of &#39;object&#39; with good starting values for<br>+#      gamma[noRegime-1] and th[noRegime-1]. It also modifies the linear<br>+#      parameters phi1 (as they are estimated for the new gamma and th).<br>+startingValues.ncstar &lt;- function(object, trace=TRUE, ...)<br>+{<br>+<br>+  noRegimes &lt;- object$model.specific$noRegimes;<br>+  xx &lt;- object$str$xx;<br>+<br>+  #Fitted values, given parameters<br>+  # phi1: matrix of linear parameters<br>+  # phi2omega: vector of tr. functions&#39; parameters<br>+  #                                     (gamma_{1...p}, th{1...p}, omega_{1...p})<br>+  F &lt;- function(phi1, phi2omega) {<br>+    # phi2 contains parameters gamma and th for each regime<br>+    phi2 &lt;- phi2omega[1:((noRegimes-1) * 2)];<br>+    dim(phi2) &lt;- c(noRegimes - 1, 2)<br>+<br>+    gamma &lt;- phi2[,1]<br>+    th &lt;- phi2[,2]<br>+<br>+    # omega (one vector for each regime)<br>+    omega &lt;- phi2omega[(((noRegimes - 1) * 2) + 1):length(phi2omega)]<br>+    dim(omega) &lt;- c(NCOL(xx), noRegimes - 1)<br>+<br>+    # To store partial results for each regime<br>+    local &lt;- array(0, c(noRegimes, n.used))<br>+<br>+    # Partial results for linear regime<br>+    local[1,] &lt;- x_t %*% phi1[1,];<br>+<br>+    for (i in 2:noRegimes)<br>+      local[i,] &lt;-<br>+        (x_t %*% phi1[i,]) *<br>+          sigmoid(gamma[i-1] * (xx %*% omega[,i-1] - th[i-1]));<br>+<br>+    result &lt;- apply(local, 2, sum)<br>+    result<br>+  }<br>+<br>+  phi2omega &lt;- object$model.specific$phi2omega<br>+<br>+  # phi2 contains parameters gamma and th for each regime<br>+  phi2 &lt;- phi2omega[1:((noRegimes-1) * 2)];<br>+  dim(phi2) &lt;- c(noRegimes - 1, 2)<br>+<br>+  gamma &lt;- phi2[,1];<br>+  th &lt;- phi2[,2];<br>+<br>+  omega &lt;- phi2omega[(((noRegimes - 1) * 2) + 1):length(phi2omega)]<br>+  dim(omega) &lt;- c(NCOL(xx), noRegimes - 1)<br>+<br>+  xx &lt;- object$str$xx;<br>+  x_t &lt;- cbind(1, xx)<br>+  yy &lt;- object$str$yy;<br>+  n.used &lt;- NROW(object$str$xx);<br>+<br>+  bestCost &lt;- Inf;<br>+<br>+  # Maximum and minimum values for gamma<br>+  maxGamma &lt;- 40;<br>+  minGamma &lt;- 10;<br>+  rateGamma &lt;- 5; ############################################!!!<br>+<br>+  # Maximum and minimum values for c<br>+  minTh &lt;- quantile(as.ts(xx[,1]), .1) # percentil 10 of s_t<br>+  maxTh &lt;- quantile(as.ts(xx[,1]), .9) # percentil 90 of s_t<br>+  rateTh &lt;- (maxTh - minTh) / 200; ################################!!!<br>+<br>+  for(newGamma in seq(minGamma, maxGamma, rateGamma)) {<br>+    for(newTh in seq(minTh, maxTh, rateTh)) {<br>+<br>+      gamma[noRegimes - 1] &lt;- newGamma;<br>+      th[noRegimes - 1] &lt;- newTh;<br>+<br>+      # We fix the linear parameters here, before optimizing the nonlinear.<br>+      tmp &lt;- rep(x_t, noRegimes)<br>+      dim(tmp) &lt;- c(NROW(x_t), NCOL(x_t), noRegimes)<br>+      for (i in 2:noRegimes)<br>+        tmp[,,i] &lt;- tmp[,,i] *<br>+          as.vector(sigmoid(gamma[i-1] * (xx %*% omega[,i-1] - th[i-1])))<br>+<br>+      newPhi1&lt;- lm(yy ~ . - 1, as.data.frame(tmp))$coefficients<br>+      dim(newPhi1) &lt;- c(NCOL(xx) + 1, noRegimes)<br>+      newPhi1 &lt;- t(newPhi1)<br>+<br>+      y.hat &lt;- F(newPhi1, c(cbind(gamma, th), omega));<br>+      cost &lt;- crossprod(yy - y.hat)<br>+<br>+      if(! <a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792465631321000&amp;usg=AOvVaw2zGJfKLCjVGR-zrB9gOzKY">is.na</a>(cost)) {<br>+        if(cost &lt;= bestCost) {<br>+          bestCost &lt;- cost;<br>+          bestGamma &lt;- gamma[noRegimes - 1];<br>+          bestTh &lt;- th[noRegimes - 1];<br>+          phi1 &lt;- newPhi1;<br>+        }<br>+      }<br>+    }<br>+  }<br>+<br>+  gamma[noRegimes - 1] &lt;- bestGamma;<br>+  th[noRegimes - 1] &lt;- bestTh;<br>+<br>+  if (trace) cat(&quot;Starting values fixed for regime &quot;, noRegimes,<br>+                 &quot;
   gamma = &quot;, gamma[noRegimes - 1],<br>+                 &quot;, th = &quot;, th[noRegimes - 1],<br>+                 &quot;; SSE = &quot;, bestCost, &quot;
&quot;);<br>+<br>+#  if(trace) {<br>+#    cat(&quot;   Starting linear values: 
